head.script:
scwin.onpageload = function() {
    dataList1.setData([1, 'a', 2, 'b', 3, 'c', 4, 'd', 5, 'e', 6, 'f', 6, 'g']);
};
scwin.onpageunload = function() {};
scwin.custom_oncontextopen = function(row, col) {
    // return false; // 컨텍스트 메뉴를 보여주지 않습니다.
    // return { hideSystemMenu: false } // 전체 시스템 메뉴를 보여주지 않습니다.
    var appendMenuList = [];
    appendMenuList.push({
        label: "컬럼 틀고정",
        userMenuId: "ColumnFix",
        className: "userMenu"
    });
    if (gridview1.options.fixedColumn > 0) {
        appendMenuList.push({
            label: "컬럼 틀고정 취소",
            userMenuId: "ColumnUnfix",
            className: "userMenu"
        });
    }
    appendMenuList.push({
        label: "우측컬럼 틀고정",
        userMenuId: "ColumnRightFix",
        className: "userMenu"
    });
    if (gridview1.options.fixedRightColumn > 0) {
        appendMenuList.push({
            label: "우측컬럼 틀고정 취소",
            userMenuId: "ColumnRightUnfix",
            className: "userMenu"
        });
    }
    appendMenuList.push({
        label: "행 틀고정",
        userMenuId: "RowFix",
        className: "userMenu"
    });
    if (gridview1.options.fixedRow > 0) {
        appendMenuList.push({
            label: "행 틀고정 취소",
            userMenuId: "RowUnfix",
            className: "userMenu"
        });
    }
    appendMenuList.push({
        label: "그리드 컬럼 배경색",
        userMenuId: "ColumnBackgroundColor",
        className: "userMenu"
    });
    if (gridview1.getColumnBackgroundColor(col) != "") {
        appendMenuList.push({
            label: "그리드 컬럼 배경색 초기화",
            userMenuId: "UnColumnBackgroundColor",
            className: "userMenu"
        });
    }
    appendMenuList.push({
        label: "그리드 행 배경색",
        userMenuId: "RowBackgroundColor",
        className: "userMenu"
    });
    if (gridview1.getRowBackgroundColor(row) != "") {
        appendMenuList.push({
            label: "그리드 행 배경색 초기화",
            userMenuId: "UnRowBackgroundColor",
            className: "userMenu"
        });
    }
    appendMenuList.push({
        label: "그리드 컬럼 폰트색",
        userMenuId: "ColumnColor",
        className: "userMenu"
    });
    if (gridview1.getColumnColor(col) != "") {
        appendMenuList.push({
            label: "그리드 컬럼 폰트색 초기화",
            userMenuId: "UnColumnColor",
            className: "userMenu"
        });
    }
    appendMenuList.push({
        label: "그리드 행 폰트색",
        userMenuId: "RowColor",
        className: "userMenu"
    });
    if (gridview1.getRowColor(row) != "") {
        appendMenuList.push({
            label: "그리드 행 폰트색 초기화",
            userMenuId: "UnRowColor",
            className: "userMenu"
        });
    }
    appendMenuList.push({
        label: "선택 컬럼 숨기기",
        userMenuId: "userColumnHide",
        className: "userMenu"
    });
    appendMenuList.push({
        label: "전체 컬럼 숨기기 해제",
        userMenuId: "userShowAll",
        className: "userMenu"
    });
    return {
        //hideSystemMenu: [ "ColumnFix", "ColumnUnfixAll", "ColumnHide", "ColumnShowAll", "Group", "ColumnAdjustWidth", "ColumnAdjustAuto" ], // 특정 항목의 시스템 메뉴를 보여주지 않습니다.
        hideSystemMenu: ["ColumnFix"],
        appendMenu: appendMenuList
        /*
        [

        	{
        		label:"선택 컬럼 숨기기",
        		// 사용자 메뉴의 표시 문자열
        		userMenuId:"userColumnHide",
        		// 사용자 메뉴의 id, 해당 컨텍스트 메뉴가 클릭될때, 입력값으로 전달됨
        		className:"userMenu"
        		// 사용자 메뉴의 스타일 클래스 이름 
        	}, 
        	{ 
        		label : "선택 행 틀고정",
        		userMenuId : "RowFix",
        		className: "userMenu"
        	}
        	,{ 
        		label : "전체 행 틀고정 취소",
        		userMenuId : "RowUnfix",
        		className: "userMenu"
        	}

        ], // 시스템 메뉴 아래에, 사용자 메뉴를 추가합니다.
        */
    };

}

    scwin.onpageload2 = function() {
        if (typeof scwin.onpageload === "function") {
            scwin.onpageload();
        }
	    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
		}
    };
